unsigned char a[16384];for(unsigned k=0;k<iterations;k++){
      for(unsigned i=0;i<16384;i++)a[i]=1;
      for(unsigned i=2;i*i<16384;i++)if(a[i])for(unsigned j=i*i;j<16384;j+=i)a[j]=0;
