#define N 128
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
static uint32_t random_word(uint32_t *s) { *s=*s*1664525u+1013904223u; return *s; }
int main(int argc, char **argv) {
  unsigned iterations=argc>1?(unsigned)strtoul(argv[1],0,10):1;
  uint32_t state=1234567u; uint64_t checksum=0;
for(unsigned k=0;k<iterations;k++){uint32_t crc=~k;for(unsigned i=0;i<N;i++){crc^=random_word(&state)&255u;for(unsigned b=0;b<8;b++)crc=(crc>>1)^((0u-(crc&1u))&0xedb88320u);}checksum+=~crc;}
 printf("%llu\n",(unsigned long long)checksum); return 0; }

