  unsigned iterations=argc>1?(unsigned)strtoul(argv[1],0,10):1;
  uint32_t state=1234567u; uint64_t checksum=0;
uint32_t a[48],b[48],prev[49],cur[49];for(unsigned i=0;i<48;i++){a[i]=random_word(&state)&7u;b[i]=random_word(&state)&7u;}for(unsigned k=0;k<iterations;k++){for(unsigned j=0;j<=48;j++)prev[j]=j;for(unsigned i=1;i<=48;i++){cur[0]=i;for(unsigned j=1;j<=48;j++){uint32_t x=prev[j]+1,y=cur[j-1]+1,z=prev[j-1]+(a[i-1]!=b[j-1]);cur[j]=x<y?(x<z?x:z):(y<z?y:z);}for(unsigned j=0;j<=48;j++)prev[j]=cur[j];}checksum+=prev[48];a[k%48]^=1u;}
 printf("%llu\n",(unsigned long long)checksum); return 0; }

#define N 128
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
static uint32_t random_word(uint32_t *s) { *s=*s*1664525u+1013904223u; return *s; }
int main(int argc, char **argv) {
  unsigned iterations=argc>1?(unsigned)strtoul(argv[1],0,10):1;
  uint32_t state=1234567u; uint64_t checksum=0;
uint32_t a[N];for(unsigned k=0;k<iterations;k++){for(unsigned i=0;i<N;i++)a[i]=random_word(&state);for(unsigned start=N/2;start>0;){unsigned root=--start;uint32_t v=a[root];while(root*2+1<N){unsigned child=root*2+1;if(child+1<N&&a[child]<a[child+1])child++;if(v>=a[child])break;a[root]=a[child];root=child;}a[root]=v;}for(unsigned end=N-1;end>0;end--){uint32_t v=a[end];a[end]=a[0];unsigned root=0;while(root*2+1<end){unsigned child=root*2+1;if(child+1<end&&a[child]<a[child+1])child++;if(v>=a[child])break;a[root]=a[child];root=child;}a[root]=v;}for(unsigned i=0;i<N;i++)checksum+=(uint64_t)a[i]*(i+1u);}
 printf("%llu\n",(unsigned long long)checksum); return 0; }

